"use client";

import { useGLTF } from "@react-three/drei";
import { useMemo } from "react";
import * as THREE from "three";

// Original 32-piece GLB, generated by scripts/create-chess-set.mjs.
// A static room prop, not a playable chess game.
export default function ChessTable() {
  const { scene } = useGLTF("/models/wooden-chess-set.glb");
  const model = useMemo(() => {
    const clone = scene.clone(true);
    clone.traverse(o => {
      if (o instanceof THREE.Mesh) { o.castShadow = true; o.receiveShadow = true; }
    });
    return clone;
  }, [scene]);
  return <group position={[5.9, 0, 1.8]} rotation={[0, -.55, 0]}>
    <mesh position={[0, 1.15, 0]} castShadow receiveShadow>
      <boxGeometry args={[1.94, .13, 1.94]} />
      <meshStandardMaterial color="#68462f" roughness={.6} />
    </mesh>
    {[-.77, .77].flatMap(x => [-.77, .77].map(z =>
      <mesh key={`${x}-${z}`} position={[x, .54, z]} castShadow>
        <boxGeometry args={[.13, 1.08, .13]} />
        <meshStandardMaterial color="#4e3324" roughness={.75} />
      </mesh>
    ))}
    <primitive object={model} position={[0, 1.215, 0]} />
  </group>;
}
